```javascript src/controllers/metricsController.js
const Metric = require('../models/Metric');

exports.recordMetric = async (req, res) => {
  try {
    const { name, value, category } = req.body;
    const metric = new Metric({ name, value, category });
    await metric.save();
    res.status(201).json(metric);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
};

