        <MarkButton format="bold" icon="B" />
        <MarkButton format="italic" icon="I" />
        <MarkButton format="underline" icon="U" />
      </div>
      <Editable
        renderElement={renderElement}
        renderLeaf={renderLeaf}
        onKeyDown={event => {
          if (!event.ctrlKey) return;

          switch (event.key) {
            case 'b': {
              event.preventDefault();
              toggleMark(editor, 'bold');
              break;
            }
            case 'i': {
              event.preventDefault();
              toggleMark(editor, 'italic');
              break;
            }
          }
        }}
      />
    </Slate>
  );
};

// Leaf component for rendering formatted text
const Leaf = ({ attributes, children, leaf }) => {
  if (leaf.bold) {
    children = <strong>{children}</strong>;
  }

  if (leaf.italic) {
    children = <em>{children}</em>;
  }

  if (leaf.underline) {
    children = <u>{children}</u>;
  }

  return <span {...attributes}>{children}</span>;
};

// Element rendering
const DefaultElement = props => {
  return <p {...props.attributes}>{props.children}</p>;
};

const CodeElement = props => {
  return (
    <pre {...props.attributes}>
      <code>{props.children}</code>
    </pre>
  );
};

export default RichTextEditor;
```

4. Advanced Example: Custom Block Types
```jsx src/components/AdvancedRichTextEditor.jsx
import React, { useMemo, useState, useCallback } from 'react';
import { createEditor, Editor, Transforms } from 'slate';
import { Slate, Editable, withReact, useSlate } from 'slate-react';

const BLOCK_TYPES = ['paragraph', 'heading-one', 'heading-two', 'block-quote'];

const AdvancedRichTextEditor = () => {
  const editor = useMemo(() => withReact(createEditor()), []);

  const [value, setValue] = useState([
    {
      type: 'paragraph',
      children: [{ text: 'A line of text in a paragraph.' }],
    },
  ]);

  const renderElement = useCallback(props => {
    switch (props.element.type) {
      case 'heading-one':
        return <h1 {...props.attributes}>{props.children}</h1>;
      case 'heading-two':
        return <h2 {...props.attributes}>{props.children}</h2>;
      case 'block-quote':
        return <blockquote {...props.attributes}>{props.children}</blockquote>;
      default:
        return <p {...props.attributes}>{props.children}</p>;
    }
  }, []);

  const toggleBlockType = (editor, format) => {
    const isActive = isBlockActive(editor, format);

    Transforms.setNodes(
      editor,
      { type: isActive ? 'paragraph' : format },
      { match: n => Editor.isBlock(editor, n) }
    );
  };

  const isBlockActive = (editor, format) => {
    const [match] = Editor.nodes(editor, {
      match: n => n.type === format,
    });

    return !!match;
  };

  return (
    <Slate 
      editor={editor} 
      value={value} 
      onChange={newValue => setValue(newValue)}
    >
      <div>
        {BLOCK_TYPES.map(type => (
          <button 
            key={type}
            onMouseDown={event => {
              event.preventDefault();
              toggleBlockType(editor, type);
            }}
          >
            {type}
          </button>
        ))}
      </div>
      <Editable
        renderElement={renderElement}
        onKeyDown={event => {
          // Add custom key handlers if needed
        }}
      />
    </Slate>
  );
};

export default AdvancedRichTextEditor;
```

Key Concepts and Best Practices:
1. Use `useMemo` to create the editor to prevent unnecessary re-renders
2. Leverage `Slate` and `Editable` components for core functionality
